result:
Debounce delays API call until user stops typing N ms. Also abort stale in-flight requests, else old response can overwrite new one.

## Vanilla JS

```html
<input id="search" type="search" placeholder="Search..." />
<ul id="results"></ul>

<script>
  function debounce(fn, delay) {
    let timer;
    return (...args) => {
      clearTimeout(timer);
      timer = setTimeout(() => fn(...args), delay);
    };
  }

  let controller;

  async function search(query) {
    controller?.abort(); // cancel previous in-flight request
    if (!query.trim()) {
      document.getElementById('results').innerHTML = '';
      return;
    }
    controller = new AbortController();
    try {
      const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
        signal: controller.signal,
      });
      const data = await res.json();
      document.getElementById('results').innerHTML = data
        .map((item) => `<li>${item.name}</li>`)
        .join('');
    } catch (err) {
      if (err.name !== 'AbortError') console.error(err);
    }
  }

  const debouncedSearch = debounce(search, 300);

  document
    .getElementById('search')
    .addEventListener('input', (e) => debouncedSearch(e.target.value));
</script>
```

## React (hook)

```jsx
import { useEffect, useState } from 'react';

function useDebounce(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id); // reset timer on every keystroke
  }, [value, delay]);
  return debounced;
}

export default function Search() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const debouncedQuery = useDebounce(query, 300);

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setResults([]);
      return;
    }
    const controller = new AbortController();
    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => res.json())
      .then(setResults)
      .catch((err) => {
        if (err.name !== 'AbortError') console.error(err);
      });
    return () => controller.abort(); // cancel stale request
  }, [debouncedQuery]);

  return (
    <>
      <input
        type="search"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search..."
      />
      <ul>
        {results.map((r) => (
          <li key={r.id}>{r.name}</li>
        ))}
      </ul>
    </>
  );
}
```

Notes:
- 250–400 ms typical delay. Lower = snappier, more requests.
- Input stays controlled/instant; only fetch debounced.
- `AbortController` fixes race: slow old response no longer clobber newer results.
- Vanilla example: `item.name` injected via `innerHTML` → XSS risk if data untrusted. Use `textContent` per `<li>` in real code.
